    "th}', ${it.is_dir})\" style=\"color:#ff6b6b; text-decoration:none;\">🗑️删除</a>`;\nhtml += `\n<tr styl"
    "e=\"border-bottom:1px solid rgba(255,255,255,0.04);\">\n<td style=\"padding:8px 12px;\"><span style="
    "\"margin-right:6px;\">${icon}</span><span ${nameClick}>${escapeHtml(it.name)}</span></td>\n<td style"
    "=\"padding:8px 12px; color:var(--muted);\">${sizeStr}</td>\n<td style=\"padding:8px 12px; text-align"
    ":right;\">${actions}</td>\n</tr>\n`;\n});\ntbody.innerHTML = html;\n})\n.catch(() => {\ndocument.get"
    "ElementById('sdcardFileList').innerHTML = '<tr><td colspan=\"3\" style=\"padding:16px; text-align:ce"
    "nter; color:#ff5555\">无法连接至开发板端侧服务</td></tr>';\n});\n}\nfunction sdcardGoPath(p) {\ncurSdPath = p.st"
    "artsWith('/') ? p : '/' + p;\nsdcardRefreshList();\n}\nfunction sdcardGoUp() {\nif (curSdPath === '/"
    "' || !curSdPath) return;\nconst parts = curSdPath.split('/').filter(Boolean);\nparts.pop();\ncurSdPa"
    "th = '/' + parts.join('/');\nsdcardRefreshList();\n}\nfunction sdcardMkdir() {\nconst name = documen"
    "t.getElementById('newDirName').value.trim();\nif (!name) return;\nconst target = (curSdPath === '/' "
    "? '' : curSdPath) + '/' + name;\nfetch('/api/sdcard/mkdir', {\nmethod: 'POST',\nheaders: {'Content-T"
    "ype': 'application/json'},\nbody: JSON.stringify({path: target})\n}).then(r => r.json()).then(d => {"
    "\nif (d.success) {\ndocument.getElementById('newDirName').value = '';\nsdcardRefreshList();\n} else "
    "{\nalert('创建失败: ' + (d.error || '权限或路径错误'));\n}\n});\n}\nfunction sdcardUploadText() {\nconst fname "
    "= document.getElementById('uploadFileName').value.trim();\nconst content = document.getElementById('"
    "uploadFileContent').value;\nif (!fname) { alert('请输入目标文件名'); return; }\nconst target = (curSdPath =="
    "= '/' ? '' : curSdPath) + '/' + fname;\nfetch('/api/sdcard/upload', {\nmethod: 'POST',\nheaders: {'C"
    "ontent-Type': 'application/json'},\nbody: JSON.stringify({path: target, content: content})\n}).then("
    "r => r.json()).then(d => {\nif (d.success) {\nshowToast('✅ 文件已写入 TF 卡');\ndocument.getElementById('u"
    "ploadFileName').value = '';\ndocument.getElementById('uploadFileContent').value = '';\nsdcardRefresh"
    "List();\n} else {\nalert('保存失败: ' + (d.error || '未知错误'));\n}\n});\n}\nfunction handleLocalFileSelect"
    "ed(input) {\nif (input.files && input.files[0]) {\nconst file = input.files[0];\ndocument.getElement"
    "ById('uploadFileName').value = file.name;\nconst reader = new FileReader();\nreader.onload = functio"
    "n(e) {\ndocument.getElementById('uploadFileContent').value = e.target.result;\n};\nreader.readAsText"
    "(file);\n}\n}\nfunction sdcardDelete(p, isDir) {\nif (!confirm(`确认永久删除该${isDir ? '目录' : '文件'}：\\n${p"
    "} ？`)) return;\nfetch('/api/sdcard/delete', {\nmethod: 'POST',\nheaders: {'Content-Type': 'applicati"
    "on/json'},\nbody: JSON.stringify({path: p})\n}).then(r => r.json()).then(d => {\nif (d.success) sdca"
    "rdRefreshList();\nelse alert('删除失败: ' + (d.error || '非空或权限不足'));\n});\n}\n/* ======================="
    "=================================\n* 实时系统日志终端 (Live Terminal) - 按需轮询\n* ============================"
    "============================ */\nlet logCursor = 0;\nlet logIsPaused = false;\nlet logAutoScroll = t"
    "rue;\nlet logLinesData = [];\nconst MAX_LOG_LINES = 1500;\nfunction startLogPolling() {\nif (!logPol"
    "lTimer) {\nfetchLogs();\nlogPollTimer = setInterval(fetchLogs, 900);\n}\n}\nfunction stopLogPolling("
    ") {\nif (logPollTimer) {\nclearInterval(logPollTimer);\nlogPollTimer = null;\n}\n}\nfunction parseLo"
    "gLine(raw) {\nif (!raw) return null;\nlet level = 'I';\nif (raw.includes('[E]') || raw.includes('ERR"
    "OR') || raw.includes('<3>')) level = 'E';\nelse if (raw.includes('[W]') || raw.includes('WARN') || r"
    "aw.includes('<4>')) level = 'W';\nelse if (raw.includes('[D]') || raw.includes('DEBUG') || raw.inclu"
    "des('<7>')) level = 'D';\nelse if (raw.includes('[V]') || raw.includes('VERBOSE')) level = 'V';\nels"
    "e if (raw.includes('[I]') || raw.includes('INFO') || raw.includes('<6>')) level = 'I';\nreturn { raw"
    ": raw, level: level };\n}\nfunction renderLogEntry(entry) {\nconst div = document.createElement('div"
    "');\ndiv.className = 'log-line';\ndiv.innerHTML = `<span class=\"log-lvl-${entry.level}\">${escapeHt"
    "ml(entry.raw)}</span>`;\nreturn div;\n}\nfunction fetchLogs() {\nif (logIsPaused) return;\nfetch('/a"
    "pi/logs?cursor=' + logCursor)\n.then(r => r.json())\n.then(d => {\nif (d.cursor !== undefined) {\nlo"
    "gCursor = d.cursor;\ndocument.getElementById('logCursorTag').innerText = 'Cursor: ' + logCursor + ' "
    "B';\n}\nif (d.logs && d.logs.length > 0) {\nconst lines = d.logs.split('\\n');\nconst term = documen"
    "t.getElementById('terminalWindow');\nconst kw = document.getElementById('logFilterInput').value.trim"
    "().toLowerCase();\nconst minLvl = document.getElementById('logLevelSelect').value;\nfor (let line of"
    " lines) {\nif (!line.trim()) continue;\nconst entry = parseLogLine(line);\nlogLinesData.push(entry);"
    "\nif (logLinesData.length > MAX_LOG_LINES) logLinesData.shift();\nif (matchesFilter(entry, kw, minLv"
    "l)) {\nterm.appendChild(renderLogEntry(entry));\n}\n}\nwhile (term.children.length > MAX_LOG_LINES) "
    "{\nterm.removeChild(term.firstChild);\n}\nif (logAutoScroll) term.scrollTop = term.scrollHeight;\n}\n"
    "})\n.catch(() => {});\n}\nfunction matchesFilter(entry, kw, minLvl) {\nif (kw && !entry.raw.toLowerC"
    "ase().includes(kw)) return false;\nif (minLvl === 'all') return true;\nconst order = { 'DEBUG': 1, '"
    "INFO': 2, 'WARN': 3, 'ERROR': 4 };\nconst entryVal = { 'D': 1, 'V': 1, 'I': 2, 'W': 3, 'E': 4 }[entr"
    "y.level] || 2;\nconst targetVal = order[minLvl] || 0;\nreturn entryVal >= targetVal;\n}\nfunction ap"
    "plyLogFilter() {\nconst term = document.getElementById('terminalWindow');\nterm.innerHTML = '';\ncon"
    "st kw = document.getElementById('logFilterInput').value.trim().toLowerCase();\nconst minLvl = docume"
    "nt.getElementById('logLevelSelect').value;\nconst frag = document.createDocumentFragment();\nfor (le"
    "t entry of logLinesData) {\nif (matchesFilter(entry, kw, minLvl)) {\nfrag.appendChild(renderLogEntry"
    "(entry));\n}\n}\nterm.appendChild(frag);\nif (logAutoScroll) term.scrollTop = term.scrollHeight;\n}\n"
    "function changeLogLevel(val) {\napplyLogFilter();\nif (val !== 'all') {\nfetch('/api/logs/level', {\n"
    "method: 'POST',\nheaders: {'Content-Type': 'application/json'},\nbody: JSON.stringify({level: val})\n"
    "}).catch(() => {});\n}\n}\nfunction toggleAutoScroll() {\nlogAutoScroll = !logAutoScroll;\nconst btn"
    " = document.getElementById('autoScrollBtn');\nbtn.innerText = logAutoScroll ? '⏬ 滚屏: 开' : '⏸️ 滚屏: 关'"
    ";\nbtn.style.borderColor = logAutoScroll ? 'var(--accent)' : 'var(--border)';\n}\nfunction toggleLog"
    "Pause() {\nlogIsPaused = !logIsPaused;\nconst btn = document.getElementById('pauseLogBtn');\nconst b"
    "adge = document.getElementById('logStreamBadge');\nif (logIsPaused) {\nbtn.innerText = '▶️ 继续';\nbad"
    "ge.innerText = '⏸️ 已暂停';\nbadge.style.color = 'var(--muted)';\n} else {\nbtn.innerText = '⏸️ 暂停';\nb"
    "adge.innerText = '● 实时监听中';\nbadge.style.color = 'var(--accent-sub)';\n}\n}\nfunction clearLocalLogs"
    "() {\nlogLinesData = [];\ndocument.getElementById('terminalWindow').innerHTML = '<div class=\"log-li"
    "ne\" style=\"color:var(--muted)\">[UI] 视图已清空</div>';\n}\nfunction clearDeviceLogs() {\nif (!confirm("
    "'确认清空端侧循环日志缓冲区？')) return;\nfetch('/api/logs/clear', {method: 'POST'})\n.then(r => r.json())\n.then("
    "() => {\nclearLocalLogs();\nlogCursor = 0;\ndocument.getElementById('logCursorTag').innerText = 'Cur"
    "sor: 0 B';\n})\n.catch(() => alert('清空失败'));\n}\nfunction exportLogs() {\nconst text = logLinesData."
    "map(e => e.raw).join('\\n');\nconst blob = new Blob([text], {type: 'text/plain;charset=utf-8'});\nco"
    "nst url = URL.createObjectURL(blob);\nconst a = document.createElement('a');\na.href = url;\na.downl"
    "oad = 'phoenix_logs_' + new Date().toISOString().replace(/[:.]/g, '-') + '.log';\na.click();\nURL.re"
    "vokeObjectURL(url);\n}\n/* ========================================================\n* 工具与辅助函数\n* =="
    "====================================================== */\nfunction formatBytes(b) {\nif (!b || b =="
    "= 0) return '0 B';\nconst k = 1024;\nconst sizes = ['B', 'KB', 'MB', 'GB'];\nconst i = Math.floor(Ma"
    "th.log(b) / Math.log(k));\nreturn (b / Math.pow(k, i)).toFixed(1) + ' ' + sizes[i];\n}\nfunction esc"
    "apeHtml(s) {\nif (!s) return '';\nreturn String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').repl"
    "ace(/>/g, '&gt;').replace(/\"/g, '&quot;');\n}\nfunction syncClientTimeToDevice() {\nconst ts = Math"
    ".floor(Date.now() / 1000);\nfetch('/api/system/time', {\nmethod: 'POST',\nheaders: {'Content-Type': "
    "'application/json'},\nbody: JSON.stringify({timestamp: ts})\n}).catch(() => {});\n}\ndocument.addEve"
    "ntListener('visibilitychange', () => {\nif (document.hidden) {\nif (statusPollTimer) clearInterval(s"
    "tatusPollTimer);\nstatusPollTimer = setInterval(refreshStatus, 5000);\n} else {\nif (statusPollTimer"
    ") clearInterval(statusPollTimer);\nstatusPollTimer = setInterval(refreshStatus, 2000);\nrefreshStatu"
    "s();\n}\n});\nrefreshStatus();\nstatusPollTimer = setInterval(refreshStatus, 2000);\nloadAgentConfig"
    "();\nrefreshAgentTools();\nsyncClientTimeToDevice();\n</script>\n</body>\n</html>";

